function Set-WinOptimizerProfile {param([ValidateSet("Gaming","Balanced","Laptop")][string]$Profile);Show-Header;Write-Host "PERFIL: $Profile" -ForegroundColor Yellow;if($Profile -eq "Gaming"){Write-Host "Plano Alto desempenho. Nao desativa Update, Defender ou servicos criticos.";$guid="8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c"}else{Write-Host "Plano Equilibrado, adequado para uso geral/bateria.";$guid="381b4222-f694-41f0-9685-ff5bb260df2e"};if(-not(Confirm-WinOptimizerAction "Aplicar perfil?")){return};powercfg /setactive $guid;Write-Status "Perfil $Profile aplicado." Green;Save-AppliedChange Perfil "Perfil $Profile" "Plano de energia alterado.";Pause-WinOptimizer}